	void setNode(ComponentNode node) {
		compNode = node;
	}

	/**
	 * {@return the componentNode containing this placeholder}
	 */
	ComponentNode getNode() {
		return compNode;
	}

	void showHeader(bool b) {
		this.showHeader = b;
		invalidateComponentNode();
	}

	bool isHeaderShowing() {
		return showHeader;
	}

	bool isParented() {
		return compNode != null;
	}

	/**
	 * Returns true if the component is showing and visible to the user.
	 * @return true if showing
	 * @see #isActive()
	 */
	bool isShowing() {
		return isShowing && comp != null && comp.isShowing();
	}

	/**
	 * Returns true if this provider wants to be showing and has a component provider, regardless 
	 * of whether the provider is showing to the user.
	 * @return true if active
	 * @see #isShowing()
	 */
	bool isActive() {
		return isShowing && componentProvider != null;
	}

	/**
	 * True signals that the showing state of the placeholder is true.  This is used to re-show
	 * providers after restoring from XML.
	 * @return True signals that the showing state of the placeholder is true
	 */
	bool wantsToBeShowing() {
		return isShowing;
	}

	private void invalidateComponentNode() {
		if (compNode != null) {
			compNode.invalidate();
		}
	}

	string getGroup() {
		if (componentProvider != null) {
			group = getGroup(componentProvider);
		}
		return group;
	}

	DetachedWindowNode getDetachedWindowNode() {
		Node node = compNode.parent;
		while (node != null) {
			if (node is DetachedWindowNode) {
				return (DetachedWindowNode) node;
			}
			node = node.parent;
		}
		return null;
	}

	WindowNode getWindowNode() {
		Node node = compNode.parent;
		while (node != null) {
			if (node is WindowNode) {
				return (WindowNode) node;
			}
			node = node.parent;
		}
		return null;
	}

	WindowNode getTopLevelNode() {
		if (compNode == null) {
			return null;
		}
		return compNode.getTopLevelNode();
	}

	/**
	 * Call to signal that this placeholder is not being used.  This is needed when placeholders
	 * are restored from XML as being visible, but then no provider can be found for them.
	 */
	void reset() {
		show(false);
	}

	/**
	 * Sets the active state.
	 * @param doShow true to show the component, false to hide it.
	 */
	void show(bool doShow) {
		if (doShow == isShowing) {
			return;
		}

		isShowing = doShow;

		invalidate();
	}

	private void hideComponent() {
		if (componentProvider == null) {
			return;
		}

		JComponent component = componentProvider.getComponent();
		if (component == null) {
			return; // can happen during initialization
		}

		Container parent = component.getParent();
		if (parent != null) {
			parent.remove(component);
		}
	}

	private void invalidate() {
		// Hide the component provider's component before clearing the UI.  If we later dispose the
		// component provider and the component is still visible, it may get repainted after being
		// disposed, which can trigger exceptions.
		hideComponent();
		invalidateComponentNode();
		disposeDockableComponent();
		notifyProviderVisibilityIsChanging();
	}

	private void notifyProviderVisibilityIsChanging() {
		if (componentProvider == null) {
			return;
		}

		if (isShowing) {
			componentProvider.componentShown();
		}
		else {
			componentProvider.componentHidden();
		}
	}

	public bool isDisposed() {
		return disposed;
	}

	void dispose() {
		disposed = true;
		disposeDockableComponent();
		disposeNode();
	}

	/**
	 * Performs a final removal of this placeholder from its {@link ComponentNode}.
	 */
	private void disposeNode() {
		if (compNode == null) {
			return;
		}

		WindowNode windowNode = compNode.getTopLevelNode();
		if (windowNode != null) {
			windowNode.componentRemoved(this);
		}

		compNode.remove(this);
		compNode = null;
	}

	/**
	 * Disposes the active {@link DockableComponent}.  The component may later get recreated in the
	 * call to {@link #getComponent()}.
	 */
	private void disposeDockableComponent() {
		if (comp == null) {
			return;
		}

		comp.dispose();
		comp = null;
	}

	/**
	 * {@return true if this placeholder has a component that can take focus.  This placeholder 
	 * cannot take focus if it does not yet have a DockableComponent.}
	 */
	bool canTakeFocus() {
		return comp != null;
	}

	void toFront() {
		if (comp != null) {
			compNode.makeSelectedTab(this);
		}
	}

	/**
	 * Requests focus for the component associated with this placeholder.
	 */
	void requestFocusWhenReady() {
		DockableComponent tmp = comp;// put in temp variable in case another thread deletes it
		if (tmp == null) {
			return;
		}

		compNode.makeSelectedTab(this);
		activateWindow();

		// make sure the tab has time to become active before trying to request focus
		ExpiringSwingTimer.runWhen(this.isShowing, () => {
			doRequestFocus(tmp);
		});
	}

	private void doRequestFocus(DockableComponent dockableComponent) {
		KeyboardFocusManager kfm = KeyboardFocusManager.getCurrentKeyboardFocusManager();
		Window activeWindow = kfm.getActiveWindow();
		if (activeWindow == null) {
			return; // our application isn't focused--don't do anything
		}

		dockableComponent.requestFocus();
		contextChanged();
	}

	// makes sure that the given window is not in an iconified state
	private void activateWindow() {
		DetachedWindowNode windowNode = getDetachedWindowNode();
		if (windowNode != null) {
			Window window = getDetachedWindowNode().getWindow();
			if (window is Frame) {
				Frame frame = (Frame) window;
				frame.setState(Frame.NORMAL);
			}
		}
	}

	/**
	 * Hides the component associated with this placeholder and notifies the provider that
	 * the component has been hidden.
	 *
	 */
	void close() {
		if (componentProvider != null) {
			componentProvider.closeComponent();
		}
	}

	/**
	 * Returns a Dockable component that wraps the component for this placeholder
	 * @return the component
	 */
	public DockableComponent getComponent() {
		if (disposed) {
			throw new AssertException(
				"Attempted to get a component for a disposed placeholder - " + this);
		}

		bool isDocking = true;
		if (compNode != null) {
			isDocking = compNode.winMgr.isDocking();
		}

		if (comp == null && isShowing) {
			comp = new DockableComponent(this, isDocking);
		}
		return comp;
	}

	void setIcon(Icon icon) {
		icon = DockingUtils.scaleIconAsNeeded(icon);

		this.icon = icon;
		if (comp != null) {
			comp.setIcon(icon);
		}
		if (compNode != null) {
			compNode.iconChanged(this);
		}
	}

	Icon getIcon() {
		return icon;
	}

	/**
	 * Returns the title for this component
	 * @return the title for this component
	 */
	public string getTitle() {
		return title;
	}

	/**
	 * Returns the subtitle for the component
	 * @return the subtitle for the component
	 */
	public string getSubTitle() {
		return subTitle;
	}

	/**
	 * The text for display on the tab of a tabbed component.
	 * @return The text for display on the tab of a tabbed component.
	 */
	public string getTabText() {
		return tabText;
	}

	/**
